CREATE PROCEDURE [Setup_bulkupdate]
	@sync_min_timestamp BigInt,
	@sync_scope_local_id Int,
	@changeTable [Setup_BulkType] READONLY
AS
BEGIN
-- use a temp table to store the list of PKs that successfully got updated
declare @changed TABLE ([IDPost] tinyint, PRIMARY KEY ([IDPost]));

-- update the base table
MERGE [Setup] AS base USING
-- join done here against the side table to get the local timestamp for concurrency check
(SELECT p.*, t.update_scope_local_id, t.scope_update_peer_key, t.local_update_peer_timestamp FROM @changeTable p LEFT JOIN [Setup_tracking] t ON p.[IDPost] = t.[IDPost]) as changes ON changes.[IDPost] = base.[IDPost]
WHEN MATCHED AND (changes.update_scope_local_id = @sync_scope_local_id AND changes.scope_update_peer_key = changes.sync_update_peer_key) OR changes.local_update_peer_timestamp <= @sync_min_timestamp THEN
UPDATE SET [MName] = changes.[MName], [NRep2] = changes.[NRep2], [NRep3] = changes.[NRep3], [NRep4] = changes.[NRep4], [NRep5] = changes.[NRep5], [NRep6] = changes.[NRep6], [NRep7] = changes.[NRep7], [NRep8] = changes.[NRep8], [NRep9] = changes.[NRep9], [ARep2] = changes.[ARep2], [ARep3] = changes.[ARep3], [ARep4] = changes.[ARep4], [ARep5] = changes.[ARep5], [ARep6] = changes.[ARep6], [ARep7] = changes.[ARep7], [ARep8] = changes.[ARep8], [ARep9] = changes.[ARep9], [VelDia] = changes.[VelDia], [TSSNum0] = changes.[TSSNum0], [TSSNum1] = changes.[TSSNum1], [TSSNum2] = changes.[TSSNum2], [TSSNum3] = changes.[TSSNum3], [TSSNum4] = changes.[TSSNum4], [TSSNum5] = changes.[TSSNum5], [TSSNum6] = changes.[TSSNum6], [TSSNum7] = changes.[TSSNum7], [TSSNum8] = changes.[TSSNum8], [TSSNum9] = changes.[TSSNum9], [Passw] = changes.[Passw], [TotTick] = changes.[TotTick], [DataEnd] = changes.[DataEnd], [DataIni] = changes.[DataIni], [NImp] = changes.[NImp], [PBonus] = changes.[PBonus], [FPPremio] = changes.[FPPremio], [FForza] = changes.[FForza], [NomeLocale] = changes.[NomeLocale], [IndiLocale] = changes.[IndiLocale], [CittaLocale] = changes.[CittaLocale], [ProvLocale] = changes.[ProvLocale], [TelLocale] = changes.[TelLocale], [numcommMT1] = changes.[numcommMT1], [numcommMT2] = changes.[numcommMT2], [numcommMT3] = changes.[numcommMT3], [numcommMT4] = changes.[numcommMT4], [numcommMT5] = changes.[numcommMT5], [numcommCR] = changes.[numcommCR], [numcommBR] = changes.[numcommBR], [numcommPR] = changes.[numcommPR], [NConc] = changes.[NConc], [NTrack] = changes.[NTrack], [ScoMan] = changes.[ScoMan], [Ric25] = changes.[Ric25], [Pre25] = changes.[Pre25], [TypePrt] = changes.[TypePrt], [SecMonX] = changes.[SecMonX], [SecMonY] = changes.[SecMonY], [OpRig] = changes.[OpRig], [Lang] = changes.[Lang], [Log] = changes.[Log], [MultiUser] = changes.[MultiUser], [CardReader] = changes.[CardReader], [CBarC] = changes.[CBarC], [NCogn] = changes.[NCogn], [OpResi] = changes.[OpResi], [VisP0] = changes.[VisP0], [FT24H] = changes.[FT24H], [NT24H] = changes.[NT24H], [FTNew] = changes.[FTNew], [PInter] = changes.[PInter], [FTBDay] = changes.[FTBDay], [FPrPr] = changes.[FPrPr], [FPrCr] = changes.[FPrCr], [ScPromo] = changes.[ScPromo], [ScLun] = changes.[ScLun], [ScMar] = changes.[ScMar], [ScMer] = changes.[ScMer], [ScGio] = changes.[ScGio], [ScVen] = changes.[ScVen], [ScSab] = changes.[ScSab], [ScDom] = changes.[ScDom], [OraPIni] = changes.[OraPIni], [OraPEnd] = changes.[OraPEnd], [DataPIni] = changes.[DataPIni], [DataPEnd] = changes.[DataPEnd], [AddSP] = changes.[AddSP], [PrNoSc] = changes.[PrNoSc], [TmOpen] = changes.[TmOpen], [TmClose] = changes.[TmClose], [OpScoMan] = changes.[OpScoMan], [AutoNT] = changes.[AutoNT], [NTMolt] = changes.[NTMolt], [OpCli] = changes.[OpCli], [MQPrem] = changes.[MQPrem], [VisNome] = changes.[VisNome], [AutoConv] = changes.[AutoConv], [TicStat] = changes.[TicStat], [BkDisk] = changes.[BkDisk], [CRaw] = changes.[CRaw], [PercAbb] = changes.[PercAbb], [NTAbb] = changes.[NTAbb], [PasswSM] = changes.[PasswSM], [MagPremLoc] = changes.[MagPremLoc], [PTBon] = changes.[PTBon], [BTLun] = changes.[BTLun], [BTMar] = changes.[BTMar], [BTMer] = changes.[BTMer], [BTGio] = changes.[BTGio], [BTVen] = changes.[BTVen], [BTSab] = changes.[BTSab], [BTDom] = changes.[BTDom], [OraBIni] = changes.[OraBIni], [OraBEnd] = changes.[OraBEnd], [DataBIni] = changes.[DataBIni], [DataBEnd] = changes.[DataBEnd], [AbPr] = changes.[AbPr], [AbBt] = changes.[AbBt], [InvPass] = changes.[InvPass], [ManAdd] = changes.[ManAdd], [OpMPremi] = changes.[OpMPremi], [OpALOff] = changes.[OpALOff], [HideList] = changes.[HideList], [HideMov] = changes.[HideMov], [FndCod] = changes.[FndCod], [NoInatt] = changes.[NoInatt], [OpRapp] = changes.[OpRapp], [NoOAcq] = changes.[NoOAcq], [VinPrInatt] = changes.[VinPrInatt], [Inv0] = changes.[Inv0], [BkpOk] = changes.[BkpOk], [Easys] = changes.[Easys], [FornMan] = changes.[FornMan], [POMan] = changes.[POMan], [MdbSaveInt] = changes.[MdbSaveInt], [OpAppL] = changes.[OpAppL], [NewConc] = changes.[NewConc], [IniConc] = changes.[IniConc], [BandaMag] = changes.[BandaMag], [RegInc] = changes.[RegInc], [IncDay] = changes.[IncDay], [LastInc] = changes.[LastInc], [IncIva] = changes.[IncIva], [CanPO] = changes.[CanPO], [NoAnnAPl] = changes.[NoAnnAPl], [ValGett] = changes.[ValGett], [ValTick] = changes.[ValTick], [NtickRic] = changes.[NtickRic], [OrInv] = changes.[OrInv], [AbOrInv] = changes.[AbOrInv], [ALAggTick] = changes.[ALAggTick], [ALAggCosto] = changes.[ALAggCosto], [ALAggRis] = changes.[ALAggRis], [ALAggBarc] = changes.[ALAggBarc], [SaveScan] = changes.[SaveScan], [NoCanPr] = changes.[NoCanPr], [ModCode] = changes.[ModCode], [IdMT1] = changes.[IdMT1], [IdMT2] = changes.[IdMT2], [IdMT3] = changes.[IdMT3], [IdMT4] = changes.[IdMT4], [IdMT5] = changes.[IdMT5], [CIndir] = changes.[CIndir], [Ab4Usr] = changes.[Ab4Usr], [AbBr0] = changes.[AbBr0], [AbBr1] = changes.[AbBr1], [AbBr2] = changes.[AbBr2], [AbBr3] = changes.[AbBr3], [PBRm0] = changes.[PBRm0], [PBRm1] = changes.[PBRm1], [PBRm2] = changes.[PBRm2], [PBRm3] = changes.[PBRm3], [AbMon3] = changes.[AbMon3], [Mon3H] = changes.[Mon3H], [Mon3V] = changes.[Mon3V], [VBase] = changes.[VBase], [ConnOk] = changes.[ConnOk], [AdmPass] = changes.[AdmPass], [HSMOp] = changes.[HSMOp], [HSMMa] = changes.[HSMMa], [Mistral] = changes.[Mistral], [MisCode] = changes.[MisCode], [MisVCard] = changes.[MisVCard], [MisVSerie] = changes.[MisVSerie], [FtpPOrd] = changes.[FtpPOrd], [MisData] = changes.[MisData], [MisCard] = changes.[MisCard], [MisSerie] = changes.[MisSerie], [OpModCli] = changes.[OpModCli], [MMCosto] = changes.[MMCosto], [MMTick] = changes.[MMTick], [ALAggType] = changes.[ALAggType], [MMMSco] = changes.[MMMSco], [EndOk] = changes.[EndOk], [DataStop] = changes.[DataStop], [AbId2] = changes.[AbId2], [NomeSped] = changes.[NomeSped], [IndSped] = changes.[IndSped], [CittaSped] = changes.[CittaSped], [ProvSped] = changes.[ProvSped], [TelSped] = changes.[TelSped], [TRed] = changes.[TRed], [TGru] = changes.[TGru], [TPus] = changes.[TPus], [TAlt] = changes.[TAlt], [NewSet] = changes.[NewSet], [Master] = changes.[Master], [CodEcs] = changes.[CodEcs], [Modif] = changes.[Modif], [SyncRes] = changes.[SyncRes], [SyncEn] = changes.[SyncEn], [NRepMT1] = changes.[NRepMT1], [NRepMT2] = changes.[NRepMT2], [NRepMT3] = changes.[NRepMT3], [NRepMT4] = changes.[NRepMT4], [NRepMT5] = changes.[NRepMT5], [F0] = changes.[F0], [F1] = changes.[F1], [F2] = changes.[F2], [F3] = changes.[F3], [F4] = changes.[F4], [F5] = changes.[F5], [F6] = changes.[F6], [F7] = changes.[F7], [T0] = changes.[T0], [T1] = changes.[T1], [T2] = changes.[T2], [T3] = changes.[T3], [T4] = changes.[T4], [T5] = changes.[T5], [T6] = changes.[T6], [T7] = changes.[T7], [N0] = changes.[N0], [N1] = changes.[N1], [N2] = changes.[N2], [N3] = changes.[N3], [N4] = changes.[N4], [N5] = changes.[N5], [N6] = changes.[N6], [N7] = changes.[N7], [D0] = changes.[D0], [D1] = changes.[D1], [D2] = changes.[D2], [D3] = changes.[D3], [D4] = changes.[D4], [D5] = changes.[D5], [D6] = changes.[D6], [D7] = changes.[D7], [F8] = changes.[F8], [F9] = changes.[F9], [F10] = changes.[F10], [F11] = changes.[F11], [F12] = changes.[F12], [F13] = changes.[F13], [F14] = changes.[F14], [F15] = changes.[F15], [T8] = changes.[T8], [T9] = changes.[T9], [T10] = changes.[T10], [T11] = changes.[T11], [T12] = changes.[T12], [T13] = changes.[T13], [T14] = changes.[T14], [T15] = changes.[T15], [N8] = changes.[N8], [N9] = changes.[N9], [N10] = changes.[N10], [N11] = changes.[N11], [N12] = changes.[N12], [N13] = changes.[N13], [N14] = changes.[N14], [N15] = changes.[N15], [D8] = changes.[D8], [D9] = changes.[D9], [D10] = changes.[D10], [D11] = changes.[D11], [D12] = changes.[D12], [D13] = changes.[D13], [D14] = changes.[D14], [D15] = changes.[D15], [GCassa] = changes.[GCassa], [VCassa] = changes.[VCassa]
OUTPUT INSERTED.[IDPost] into @changed; -- populates the temp table with successful PKs

UPDATE side SET
update_scope_local_id = @sync_scope_local_id, 
scope_update_peer_key = changes.sync_update_peer_key, 
scope_update_peer_timestamp = changes.sync_update_peer_timestamp,
local_update_peer_key = 0
FROM 
[Setup_tracking] side JOIN 
(SELECT p.[IDPost], p.sync_update_peer_timestamp, p.sync_update_peer_key, p.sync_create_peer_key, p.sync_create_peer_timestamp FROM @changed t JOIN @changeTable p ON p.[IDPost] = t.[IDPost]) as changes ON changes.[IDPost] = side.[IDPost]
SELECT [IDPost] FROM @changeTable t WHERE NOT EXISTS (SELECT [IDPost] from @changed i WHERE t.[IDPost] = i.[IDPost])
END
